"""Structured schemas for AI agent proposals, explanations, and guard outputs."""
from __future__ import annotations

from datetime import datetime
from decimal import Decimal
from typing import Any

from pydantic import BaseModel, Field, field_validator

from app.core.enums import AgentAction, GuardOutcome


class AgentStrategyProposal(BaseModel):
    """Structured proposal generated by an AI participant agent."""
    action: AgentAction
    confidence: float = Field(ge=0.0, le=1.0, description="Agent confidence score in [0.0, 1.0]")
    reasoning_summary: str = Field(max_length=1000, description="Concise human-readable explanation")
    quantity_kwh: Decimal | None = Field(default=None, ge=0, description="Energy volume in kWh")
    limit_price: Decimal | None = Field(default=None, ge=0, description="Price boundary currency/kWh")
    reserve_kw: Decimal | None = Field(default=None, ge=0, description="Operating reserve capacity in kW")
    target_soc: float | None = Field(default=None, ge=0.0, le=100.0, description="Desired state-of-charge %")
    defer_until: datetime | None = Field(default=None, description="Load or charge postponement timestamp")
    assumptions: list[str] = Field(default_factory=list, description="Explicit modeling assumptions")
    risk_factors: list[str] = Field(default_factory=list, description="Identified risk factors")

    @field_validator("confidence")
    @classmethod
    def validate_confidence(cls, v: float) -> float:
        if v < 0.0 or v > 1.0:
            raise ValueError("confidence must be strictly between 0.0 and 1.0")
        return round(v, 4)

    @field_validator("quantity_kwh", "limit_price", "reserve_kw")
    @classmethod
    def validate_non_negative(cls, v: Decimal | None) -> Decimal | None:
        if v is not None and v < Decimal("0"):
            raise ValueError("Numerical quantities and prices must be non-negative")
        return v


class MetricReference(BaseModel):
    """Reference to a concrete metric supplied in observation context."""
    metric_name: str
    supplied_value: float | str
    node_or_asset: str | None = None


class ContributingFactor(BaseModel):
    """Factor explaining market behavior."""
    factor: str
    direction: str = "NEUTRAL"  # INCREASE, DECREASE, NEUTRAL
    impact_estimate: str = ""


class MarketExplanation(BaseModel):
    """Structured explanation generated by MarketAnalystAgent."""
    headline: str
    summary: str
    contributing_factors: list[ContributingFactor] = Field(default_factory=list)
    metric_references: list[MetricReference] = Field(default_factory=list)
    confidence: float = Field(default=1.0, ge=0.0, le=1.0)


class GridAdvisorProposal(BaseModel):
    """Advisory recommendation produced by GridAIAgent for system operators."""
    recommendation: str  # PROCURE_ADDITIONAL_RESERVE, REQUEST_DEMAND_RESPONSE, PREPARE_FOR_ISLANDING, INVESTIGATE_CONGESTION, INCREASE_RESILIENCE_RESERVE, NORMAL_OPERATION
    target_node: str | None = None
    target_feeder: str | None = None
    recommended_reserve_kw: float | None = None
    recommended_dr_kw: float | None = None
    urgency: str = "NORMAL"  # LOW, NORMAL, HIGH, CRITICAL
    reasoning_summary: str
    confidence: float = Field(default=1.0, ge=0.0, le=1.0)
    observed_signals: list[str] = Field(default_factory=list)


class GuardResult(BaseModel):
    """Deterministic validation and clamping output for an agent proposal."""
    status: GuardOutcome
    approved_action: AgentAction
    approved_quantity_kwh: Decimal = Decimal("0")
    approved_limit_price: Decimal | None = None
    approved_reserve_kw: Decimal | None = None
    reason_codes: list[str] = Field(default_factory=list)
    is_fallback: bool = False
    fallback_reason: str | None = None
    clamped: bool = False
    original_proposal: AgentStrategyProposal | None = None
    details: dict[str, Any] = Field(default_factory=dict)
